--- a/src/main.rs
+++ b/src/main.rs
@@ -45,7 +45,19 @@
         if relay.config.dev_cert {
             info!(certificate_sha256 = %identity.certificate_chain().as_slice()[0].hash(), "development certificate pin");
         }
-        let transport = wtransport::ServerConfig::builder().with_bind_address(relay.config.bind).with_custom_transport(identity, war_relay::webtransport::server_transport_config())
+        use wtransport::tls::rustls;
+        let default_tls = wtransport::tls::server::build_default_tls_config(identity);
+        let mut provider = rustls::crypto::ring::default_provider();
+        provider.cipher_suites.sort_by_key(|suite| {
+            suite.suite() != rustls::CipherSuite::TLS13_CHACHA20_POLY1305_SHA256
+        });
+        let mut tls = rustls::ServerConfig::builder_with_provider(std::sync::Arc::new(provider))
+            .with_protocol_versions(&[&rustls::version::TLS13])?
+            .with_no_client_auth()
+            .with_cert_resolver(default_tls.cert_resolver);
+        tls.alpn_protocols = default_tls.alpn_protocols;
+        tls.ignore_client_order = true;
+        let transport = wtransport::ServerConfig::builder().with_bind_address(relay.config.bind).with_custom_tls_and_transport(tls, war_relay::webtransport::server_transport_config())
             .keep_alive_interval((relay.config.ping_interval_secs != 0).then(|| std::time::Duration::from_secs(relay.config.ping_interval_secs)))
             .max_idle_timeout((relay.config.ping_interval_secs != 0).then(|| std::time::Duration::from_secs(relay.config.pong_timeout_secs)))?
             .build();
